// Des: Tests for the JSON answer envelope
// Flo: arena > build docs > parse them back > assert core fields
// I/O: none (pure)
// Run: zig build test -Dfile=ct-ctrl-envl-test.zig
// ===================================================================
const std = @import("std"); const envl = @import("ct-ctrl-envl.zig");
fn parz(aren: std.mem.Allocator, text: []const u8) !std.json.ObjectMap { const valu = try std.json.parseFromSliceLeaky(std.json.Value, aren, text, .{}); return valu.object; }
test "one object gets ok, cmd, exit and dry_run, its own fields stay" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const allo = aren.allocator(); const docz = try envl.okayDoc(allo, "status", 0, "{\"appz\":\"za\",\"pags\":3}\n", false); const obj = try parz(allo, docz); try std.testing.expect(obj.get("ok").?.bool); try std.testing.expectEqualStrings("status", obj.get("cmd").?.string); try std.testing.expectEqual(@as(i64, 0), obj.get("exit").?.integer); try std.testing.expect(!obj.get("dry_run").?.bool); try std.testing.expectEqual(@as(i64, 3), obj.get("pags").?.integer); }
test "a key the body already has is never doubled" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const allo = aren.allocator(); const docz = try envl.okayDoc(allo, "status", 0, "{\"ok\":true,\"x\":1}", null); try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, docz, "\"ok\"")); _ = try parz(allo, docz); }
test "plain text and many lines become one doc with lines; empty text is a bare doc" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const allo = aren.allocator(); const obj = try parz(allo, try envl.okayDoc(allo, "kill", 0, "kill switch off\nsecond \"line\"\n", null)); try std.testing.expectEqual(@as(usize, 2), obj.get("lines").?.array.items.len); const bare = try parz(allo, try envl.okayDoc(allo, "kill", 0, "", null)); try std.testing.expect(bare.get("lines") == null); try std.testing.expect(bare.get("ok").?.bool); const emty = try parz(allo, try envl.okayDoc(allo, "kill", 0, "{}", null)); try std.testing.expectEqual(@as(i64, 0), emty.get("exit").?.integer); }
test "a non-zero exit makes ok false" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const allo = aren.allocator(); const obj = try parz(allo, try envl.okayDoc(allo, "fetch", 4, "{\"stat\":\"bloc\"}", true)); try std.testing.expect(!obj.get("ok").?.bool); try std.testing.expectEqual(@as(i64, 4), obj.get("exit").?.integer); try std.testing.expect(obj.get("dry_run").?.bool); }
test "failure doc carries code in snake_case and msg" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const allo = aren.allocator(); const obj = try parz(allo, try envl.failDoc(allo, "zork", 2, "BadUsage", "bad usage: unknown flag --x", null)); try std.testing.expect(!obj.get("ok").?.bool); try std.testing.expectEqualStrings("bad_usage", obj.get("code").?.string); try std.testing.expectEqualStrings("bad usage: unknown flag --x", obj.get("msg").?.string); try std.testing.expectEqual(@as(i64, 2), obj.get("exit").?.integer); }
test "one JSON array becomes the data field" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const allo = aren.allocator(); const obj = try parz(allo, try envl.okayDoc(allo, "canary", 3, "[{\"urlz\":\"u\",\"stat\":\"drift\"}]\n", true)); try std.testing.expectEqual(@as(usize, 1), obj.get("data").?.array.items.len); try std.testing.expect(obj.get("lines") == null); try std.testing.expectEqual(@as(i64, 3), obj.get("exit").?.integer); }
